#!/usr/bin/env bash
# Gate G-D11 + NI-U5's comparison harness (Phase 14 design faza14-distribution.md §11.2 NI-U5,
# §12.1 G-D11; slice S6f):
#   - G-D11: protocol/test-vectors/wire_transcript.txt, once committed, is regenerated by
#     `cargo run -p ghost-client-net --example wire_transcript --locked` (driving every client RPC
#     against in-process tonic/h2 servers over loopback TCP with fixed inputs and rendering the
#     canonical transcript: preface, SETTINGS values, WINDOW_UPDATE presence, HEADERS shapes,
#     DATA lengths only) and must diff equal to the committed copy. A difference is either an
#     uncommitted regeneration or a real wire change; both are refused here.
#   - NI-U5 (the comparison mode): the generator takes no release input, so the transcript is
#     release-independent BY CONSTRUCTION; the mode proves it per release by regenerating the
#     transcript at the current tree AND at a reference checkout — a `git worktree` of the given
#     ref, built and run there — and requiring the two to be byte-identical. A wire change
#     between the reference and the current tree is refused here and must be acknowledged as an
#     NI-U5 entry (a wire change is never silent: a wire-neutral release is what the byte-equal
#     diff certifies). Enabled with --compare-ref <ref> or GHOST_WIRE_TRANSCRIPT_COMPARE_REF=<ref>;
#     a set-but-empty value means HEAD's first parent (the CI drill's default: the pushed head
#     against its parent). On a real release the CI job compares the closing tag against its
#     predecessor tag; until the first release the drill runs HEAD~1. Needs git (fetch-depth 0:
#     the ref and its history), cargo on both trees, and, for the committed-before check, the
#     history.
#   - before the first generation the file is absent: the gate passes with a note, but only while
#     the file has never been committed on the first-parent history (mirroring
#     entitlement-schedule.sh; a published transcript is never removed). In comparison mode the
#     note does not stop the comparison.
#   - the regeneration never touches the committed copy: the generator's output path is redirected
#     to scratch space through GHOST_WIRE_TRANSCRIPT_OUT, and the generator's printed SHA-256 must
#     match the bytes it wrote.
# Self-test hooks, honoured for fixture roots only (GHOST_ROOT other than this repository's ghost/):
#   GHOST_WIRE_TRANSCRIPT_REGEN=<file>      the current tree's regenerated transcript, instead of cargo;
#   GHOST_WIRE_TRANSCRIPT_COMPARE=<file>    the reference tree's regenerated transcript, instead of
#                                         the worktree build (the fixtures' machines have neither).
source "$(dirname "${BASH_SOURCE[0]}")/common.sh"

TRANSCRIPT_REL="protocol/test-vectors/wire_transcript.txt"
TRANSCRIPT="$GHOST_ROOT/$TRANSCRIPT_REL"
REAL_ROOT="$(cd "$GATES_DIR/../.." && pwd -P)"
# The workspace directory's path inside a repository checkout: --compare-ref's worktree is a
# checkout of the REPO root (git toplevel — the workspace may live in a subdirectory of it), so
# the reference generator runs at <worktree>/<this relative path>. Paths are normalized through
# cd because git rev-parse returns the native spelling.
REPO_ROOT="$(git -C "$GHOST_ROOT" rev-parse --show-toplevel 2>/dev/null || echo "$REAL_ROOT")"
REPO_ROOT="$(cd "$REPO_ROOT" && pwd -P)"
GHOST_SUB="${GHOST_ROOT%/}"
case "$GHOST_SUB" in
  "$REPO_ROOT")   GHOST_SUB="." ;;
  "$REPO_ROOT"/*) GHOST_SUB="${GHOST_SUB#"$REPO_ROOT"/}" ;;
  *)              GHOST_SUB="." ;;
esac
fixture_root=0
[ "$(cd "$GHOST_ROOT" && pwd -P)" = "$REAL_ROOT" ] || fixture_root=1
if [ "$fixture_root" = 0 ]; then
  for hook in GHOST_WIRE_TRANSCRIPT_REGEN GHOST_WIRE_TRANSCRIPT_COMPARE; do
    if [ -n "${!hook:-}" ]; then echo "$hook is a self-test hook for fixture roots only" >&2; exit 2; fi
  done
fi

usage() { echo "usage: wire-transcript.sh [--compare-ref <ref>]" >&2; exit 2; }
compare_ref="${GHOST_WIRE_TRANSCRIPT_COMPARE_REF-}"
while [ "$#" -gt 0 ]; do
  case "$1" in
    --compare-ref)
      [ -n "${2:-}" ] || usage
      compare_ref="$2"
      shift 2 ;;
    *) usage ;;
  esac
done
# Compare mode is on when the ref is named (--compare-ref or GHOST_WIRE_TRANSCRIPT_COMPARE_REF,
# a set-but-empty value meaning the current HEAD's first parent) or when the fixture hook names
# the reference transcript.
compare=0
if [ "${GHOST_WIRE_TRANSCRIPT_COMPARE_REF+x}" = x ] || [ -n "$compare_ref" ] \
  || [ -n "${GHOST_WIRE_TRANSCRIPT_COMPARE:-}" ]; then
  compare=1
fi

work="$(mktemp -d)"
cleanup() { rm -rf "$work"; }
trap cleanup EXIT

# Once committed on the first-parent history, the transcript is never removed.
committed_before=0
if command -v git >/dev/null \
  && git -C "$GHOST_ROOT" rev-parse --is-inside-work-tree >/dev/null 2>&1 \
  && [ "$(git -C "$GHOST_ROOT" rev-parse --is-shallow-repository 2>/dev/null)" = false ]; then
  [ -z "$(git -C "$GHOST_ROOT" log --first-parent --format=%H -- "$TRANSCRIPT_REL" 2>/dev/null | head -1)" ] \
    || committed_before=1
fi

golden_present=1
if [ ! -f "$TRANSCRIPT" ]; then
  golden_present=0
  if [ "$committed_before" = 1 ]; then
    fail "$TRANSCRIPT_REL was committed before and is now missing (a published transcript is never removed)"
    finish wire-transcript
    exit 1
  fi
  echo "[wire-transcript] $TRANSCRIPT_REL absent and never committed: the first generation is pending (cargo run -p ghost-client-net --example wire_transcript --locked, then commit the file)"
  if [ "$compare" = 0 ]; then
    finish wire-transcript
    exit 0
  fi
fi

# The current tree's regenerated side: cargo on the real tree, the fixture hook otherwise.
run_generator() { # $1 = tree dir, $2 = output file, $3 = log name
  if ! (cd "$1" && GHOST_WIRE_TRANSCRIPT_OUT="$2" cargo run --locked --quiet -p ghost-client-net --example wire_transcript) > "$work/$3.log" 2>&1; then
    cat "$work/$3.log" >&2
    return 1
  fi
  # The generator's last stdout line is the artifact's SHA-256; it must match the written bytes.
  local hash_line hash_val actual
  hash_line="$(grep '^wire_transcript.txt sha256=' "$work/$3.log" || true)"
  if [ -z "$hash_line" ]; then
    echo "the generator did not print its wire_transcript.txt sha256 line" >&2
    return 1
  fi
  hash_val="${hash_line#wire_transcript.txt sha256=}"
  hash_val="${hash_val%% *}"
  actual="$(sha256sum "$2" | cut -d' ' -f1)"
  [ "$hash_val" = "$actual" ] || { echo "the generator's printed SHA-256 ($hash_val) does not match the file it wrote ($actual)" >&2; return 1; }
}

if [ -n "${GHOST_WIRE_TRANSCRIPT_REGEN:-}" ]; then
  regen="$GHOST_WIRE_TRANSCRIPT_REGEN"
else
  command -v cargo >/dev/null || { echo "cargo not found" >&2; exit 2; }
  regen="$work/regenerated.txt"
  if ! run_generator "$GHOST_ROOT" "$regen" run; then
    fail "the wire-transcript generator did not run at the current tree"
    finish wire-transcript
    exit 1
  fi
fi

if [ "$golden_present" = 1 ]; then
  if cmp -s "$TRANSCRIPT" "$regen"; then
    echo "[wire-transcript] $TRANSCRIPT_REL matches the regenerated transcript"
  else
    diff -u "$TRANSCRIPT" "$regen" | head -40 >&2 || true
    fail "$TRANSCRIPT_REL differs from the regenerated transcript: run the generator and commit the result, or the change is a real wire change and NI-U5's release comparison must acknowledge it"
  fi
fi

# NI-U5's comparison: the reference tree's transcript must be byte-identical to the current one.
if [ "$compare" = 1 ]; then
  if [ "$fixture_root" = 1 ]; then
    if [ -z "${GHOST_WIRE_TRANSCRIPT_COMPARE:-}" ]; then
      echo "GHOST_WIRE_TRANSCRIPT_COMPARE is a self-test hook for fixture roots only: comparison mode on a fixture root needs it (no cargo, no worktree build there)" >&2
      exit 2
    fi
    ref_tx="$GHOST_WIRE_TRANSCRIPT_COMPARE"
    ref_label="${compare_ref:-the fixture reference}"
  else
    command -v git >/dev/null || { echo "git not found" >&2; exit 2; }
    command -v cargo >/dev/null || { echo "cargo not found" >&2; exit 2; }
    if [ "$(git -C "$GHOST_ROOT" rev-parse --is-shallow-repository 2>/dev/null)" = true ]; then
      fail "shallow clone: NI-U5's comparison needs the reference ref (CI: fetch-depth: 0)"
      finish wire-transcript
      exit 1
    fi
    # A set-but-empty value means the current HEAD's first parent (the CI drill's default).
    [ -n "$compare_ref" ] || compare_ref="HEAD~1"
    ref_label="$compare_ref"
    if ! ref_commit="$(git -C "$GHOST_ROOT" rev-parse --verify --quiet "$compare_ref^{commit}")"; then
      fail "NI-U5's comparison ref '$compare_ref' does not resolve to a commit"
      finish wire-transcript
      exit 1
    fi
    ref_worktree="$work/ref"
    ref_tx="$work/ref-regenerated.txt"
    if ! git -C "$GHOST_ROOT" worktree add --detach "$ref_worktree" "$ref_commit" > "$work/worktree.log" 2>&1; then
      cat "$work/worktree.log" >&2
      fail "cannot check out the comparison ref '$compare_ref' as a worktree"
      finish wire-transcript
      exit 1
    fi
    if ! run_generator "$ref_worktree/$GHOST_SUB" "$ref_tx" ref-run; then
      git -C "$GHOST_ROOT" worktree remove --force "$ref_worktree" >/dev/null 2>&1 || true
      fail "the wire-transcript generator did not run at the reference '$compare_ref'"
      finish wire-transcript
      exit 1
    fi
    git -C "$GHOST_ROOT" worktree remove --force "$ref_worktree" >/dev/null 2>&1 || true
    echo "[wire-transcript] NI-U5: regenerated the transcript at $compare_ref ($ref_commit)"
  fi
  if cmp -s "$regen" "$ref_tx"; then
    echo "[wire-transcript] NI-U5 OK: $ref_label and the current tree give byte-identical wire transcripts (the release is wire-neutral against the reference)"
  else
    diff -u "$ref_tx" "$regen" | head -40 >&2 || true
    fail "NI-U5: the wire transcript differs between $ref_label and the current tree: the release is not wire-neutral against the reference; acknowledge the wire change as an NI-U5 entry or revert it"
  fi
fi
finish wire-transcript
